package com.codepilot1c.core.edt.development;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;import java.util.*;import java.nio.file.*;
public class StartupConsentServiceTest {
 @Rule public TemporaryFolder tmp=new TemporaryFolder();Path root;String question="a".repeat(64);int effects;boolean unknown;boolean stopped;boolean drift;
 Map<String,Object> scope=Map.of("base_uuid","base","capability","native_external");
 StartupConsentService.Context context=()->{if(stopped)throw new IllegalStateException("stopped");return Map.of("consent_scope",drift?Map.of("base_uuid","foreign"):scope);};
 StartupConsentService.Adapter adapter=(ctx,op)->{if("inspect".equals(op.get("operation")))return Map.of("success",true,"question_sha256",question,"question_kind","external_epf_trust","text","Owned EPF?","window_id","private");effects++;return unknown?Map.of("success",false,"outcome_unknown",true):Map.of("success",true,"dialog_departed",true);};
 @Before public void init()throws Exception{root=tmp.newFolder().toPath();}
 Map<String,Object> inspect()throws Exception{return StartupConsentService.inspect(root,context,"edt_runtime_host",Map.of("host_id","own"),adapter);}
 Map<String,Object> request()throws Exception{var r=inspect();var auth=Map.of("base_uuid","base","scope_sha256",r.get("scope_sha256"),"question_sha256",question,"answer","allow","allow_foreground_input",true);return new LinkedHashMap<>(Map.of("action","startup_answer","host_id","own","idempotency_key","answer","expected_question_sha256",question,"answer","allow","authorization",auth));}
 @Test public void answerIsDurableAndNeverMeansRuntimeReady()throws Exception {var a=request();var r=StartupConsentService.answer(root,context,a,adapter);assertEquals(true,r.get("success"));assertEquals(false,r.get("ready"));stopped=true;assertEquals(r,StartupConsentService.answer(root,context,a,adapter));assertEquals(1,effects);}
 @Test public void newKeyNeverRepeatsSameQuestion()throws Exception {var a=request();StartupConsentService.answer(root,context,a,adapter);a.put("idempotency_key","another");assertThrows(IllegalStateException.class,()->StartupConsentService.answer(root,context,a,adapter));assertEquals(1,effects);}
 @Test public void changedPayloadCannotReuseKey()throws Exception {var a=request();StartupConsentService.answer(root,context,a,adapter);a.put("answer","deny");assertThrows(IllegalArgumentException.class,()->StartupConsentService.answer(root,context,a,adapter));}
 @Test public void missingExplicitInputAuthorizationNeverDispatches()throws Exception {var a=request();a.remove("authorization");assertThrows(IllegalArgumentException.class,()->StartupConsentService.answer(root,context,a,adapter));assertEquals(0,effects);}
 @Test public void scopeDriftNeverDispatches()throws Exception {var a=request();drift=true;assertThrows(IllegalStateException.class,()->StartupConsentService.answer(root,context,a,adapter));assertEquals(0,effects);}
 @Test public void unknownAnswerBlocksLaterQuestionAndOrdinaryUse()throws Exception {var a=request();unknown=true;StartupConsentService.answer(root,context,a,adapter);question="b".repeat(64);var r=inspect();assertEquals(false,r.get("answer_available"));assertTrue(((List<?>)TaskSessionService.object(r.get("decision")).get("options")).isEmpty());assertThrows(IllegalStateException.class,()->StartupConsentService.requireNoUnknown(root));assertEquals(1,effects);}
 @Test public void newProvenQuestionAfterSuccessfulAnswerHasOwnDecision()throws Exception {var a=request();StartupConsentService.answer(root,context,a,adapter);question="b".repeat(64);var r=inspect();assertEquals(true,r.get("answer_available"));assertEquals(2,((List<?>)TaskSessionService.object(r.get("decision")).get("options")).size());}
 @Test public void onlyProvenNoInputForegroundPauseCanContinueSameKey()throws Exception {
  var request=request();var preflights=new java.util.concurrent.atomic.AtomicInteger();StartupConsentService.Adapter paused=(ctx,op)->{if(preflights.getAndIncrement()==0)return Map.of("success",false,"action_dispatched",false,"outcome_unknown",false,"reason","foreground_unavailable","stage","activate_own_dialog");effects++;return Map.of("success",true,"action_dispatched",true,"dialog_departed",true);};
  var first=StartupConsentService.answer(root,context,request,paused);assertEquals("awaiting_foreground",first.get("state"));assertEquals(0,effects);assertTrue(first.containsKey("continuation_call"));var second=StartupConsentService.answer(root,context,request,paused);assertEquals(true,second.get("success"));StartupConsentService.answer(root,context,request,paused);assertEquals(1,effects);assertEquals(2,preflights.get());
 }
 @Test public void foregroundContinuationIsBoundedAndNeverUsesNewKey()throws Exception {
  var request=request();StartupConsentService.Adapter paused=(ctx,op)->Map.of("success",false,"action_dispatched",false,"outcome_unknown",false,"reason","foreground_unavailable","stage","activate_own_dialog");for(int i=0;i<3;i++)StartupConsentService.answer(root,context,request,paused);var last=StartupConsentService.answer(root,context,request,paused);assertEquals("manual_required",last.get("state"));assertFalse(last.containsKey("continuation_call"));request.put("idempotency_key","new-key");assertThrows(IllegalStateException.class,()->StartupConsentService.answer(root,context,request,paused));assertEquals(0,effects);
 }
 @Test public void missingUnknownProofNeverAuthorizesForegroundContinuation()throws Exception {var request=request();var calls=new java.util.concurrent.atomic.AtomicInteger();StartupConsentService.Adapter incomplete=(ctx,op)->{calls.incrementAndGet();return Map.of("success",false,"action_dispatched",false,"reason","foreground_unavailable","stage","activate_own_dialog");};var first=StartupConsentService.answer(root,context,request,incomplete);assertFalse(first.containsKey("continuation_call"));StartupConsentService.answer(root,context,request,incomplete);assertEquals(1,calls.get());}
}
